/* Nature Fitness service worker. Generated by scripts/build-sw.mjs. */
const VERSION = '__VERSION__';
const PRECACHE = __PRECACHE__;
const APP_CACHE = 'app-' + VERSION;
const OCR_CACHE = 'ocr-v1';
const FONT_CACHE = 'fonts-v1';

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(APP_CACHE).then((c) => c.addAll(PRECACHE)).then(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((keys) =>
      Promise.all(keys.filter((k) => k.startsWith('app-') && k !== APP_CACHE).map((k) => caches.delete(k))),
    ).then(() => self.clients.claim()),
  );
});

async function cacheFirst(cacheName, request) {
  const cache = await caches.open(cacheName);
  const hit = await cache.match(request);
  if (hit) return hit;
  const res = await fetch(request);
  if (res.ok) cache.put(request, res.clone());
  return res;
}

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return; // Supabase and other APIs go straight to the network.

  if (url.pathname.startsWith('/ocr/')) {
    event.respondWith(cacheFirst(OCR_CACHE, req));
    return;
  }
  if (req.mode === 'navigate') {
    // Pages: serve the cached copy for this path (or the home page), so the
    // app opens offline; fall back to the network for anything unknown.
    event.respondWith((async () => {
      const cache = await caches.open(APP_CACHE);
      const path = url.pathname.endsWith('/') ? url.pathname : url.pathname + '/';
      return (await cache.match(path)) || (await cache.match('/')) || fetch(req);
    })());
    return;
  }
  event.respondWith((async () => {
    const cache = await caches.open(APP_CACHE);
    const hit = await cache.match(req, { ignoreSearch: url.pathname.startsWith('/_next/') });
    if (hit) return hit;
    try {
      return await fetch(req);
    } catch (e) {
      return cacheFirst(FONT_CACHE, req);
    }
  })());
});

self.addEventListener('message', (event) => {
  if (event.data === 'skip-waiting') self.skipWaiting();
});
